CREATE TABLE sellable_products (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, marketplace_product_id UUID NOT NULL, store_id UUID NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uq_sellable_product_tenant_marketplace UNIQUE (tenant_id, marketplace_product_id));
CREATE TABLE prices (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, sellable_product_id UUID NOT NULL REFERENCES sellable_products(id), amount NUMERIC(19,4) NOT NULL, currency VARCHAR(3) NOT NULL, valid_from TIMESTAMP WITH TIME ZONE NOT NULL, valid_until TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_price_period CHECK (valid_until > valid_from));
CREATE TABLE commercial_rules (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, name VARCHAR(255) NOT NULL, description TEXT, type VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sellable_products_tenant_id ON sellable_products(tenant_id); CREATE INDEX idx_sellable_products_marketplace_id ON sellable_products(marketplace_product_id); CREATE INDEX idx_sellable_products_status ON sellable_products(status); CREATE INDEX idx_prices_tenant_id ON prices(tenant_id); CREATE INDEX idx_prices_product_id ON prices(sellable_product_id); CREATE INDEX idx_prices_status ON prices(status); CREATE INDEX idx_rules_tenant_id ON commercial_rules(tenant_id);
